"""Inventory of result directories and seed blocks, generated by scanning the stored files:
  tables/inventory.csv     per result directory: files, seeds (min-max, count), splits, budgets, learners, selectors, which declared block its seeds fall into
  tables/seed_blocks.csv   the declared blocks of pp_registry.SEED_BLOCKS with the check results
Fails (AssertionError) if two declared blocks overlap, or if a confirmation directory contains seeds outside its block."""
import glob
import json

import pandas as pd

import pp_lib as L
from pp_lib import RES
from pp_registry import SEED_BLOCKS, STUDIES

CONFIRM_DIRS = {  # directory -> declared block (study, role)
    "confirm1": ("ND", "confirmation (ND1: anchor weight / selection)"), "confirm3_cold": ("ND", "confirmation (ND3: cold start)"), "confirm4_htr": ("ND", "confirmation (ND4: HTR)"), "confirm5_gp": ("ND", "confirmation (ND5: GP learner)"),
    "gl/confirm1": ("GL", "confirmation 1"), "gl/confirm2": ("GL", "confirmation 2"), "gl/cold": ("GL", "cold-start confirmation"),
    "gm/confirm1": ("GM", "confirmation 1"), "gm/confirm2": ("GM", "confirmation 2"),
    "sh/c1_learn": ("SH", "confirmation 1"), "sh/c1_sel": ("SH", "confirmation 1"), "sh/c1_sel4": ("SH", "confirmation 1"), "sh/c2_learn": ("SH", "confirmation 2"), "sh/c2_sel": ("SH", "confirmation 2"), "sh/cold_learn": ("SH", "cold-start confirmation"),
    "ge/conf1_class": ("GE", "confirmation 1"), "ge/conf1_dose": ("GE", "confirmation 1"), "ge/conf1_harsh": ("GE", "confirmation 1"), "ge/conf2_class": ("GE", "confirmation 2"), "ge/conf2_dose": ("GE", "confirmation 2"), "ge/conf2_harsh": ("GE", "confirmation 2"),
}


def main():
    blocks = pd.DataFrame(SEED_BLOCKS, columns=["study", "role", "first", "last"]); blocks["n_seeds"] = blocks["last"] - blocks["first"] + 1
    for i, a in blocks.iterrows():
        for j, b in blocks.iterrows():
            if i < j: assert a["last"] < b["first"] or b["last"] < a["first"], f"seed blocks overlap: {a.study}/{a.role} and {b.study}/{b.role}"
    rows = []
    for d in sorted(p for p in glob.glob(str(RES / "**" / "*"), recursive=True) if (RES.joinpath(p).is_dir())):
        rel = str(RES.joinpath(d).relative_to(RES)); files = sorted(glob.glob(f"{d}/seed*"))
        if not files: continue
        seeds, learners, selectors, splits, budgets = set(), set(), set(), set(), set()
        for f in files:
            import re
            m = re.search(r"seed(\d+)", f); seeds.add(int(m.group(1)))
            if f.endswith(".json"):
                try: recs = json.loads(open(f).read())
                except Exception: continue
                if isinstance(recs, list):
                    for r in recs:
                        if isinstance(r, dict):
                            learners.add(r.get("learner") or r.get("variant") or r.get("arm") or r.get("method")); selectors.add(r.get("selector")); splits.add(r.get("split")); budgets.add(r.get("budget"))
        block = next((f"{s}: {r}" for s, r, a, b in SEED_BLOCKS if min(seeds) >= a and max(seeds) <= b), "")
        if rel in CONFIRM_DIRS:
            s_, r_ = CONFIRM_DIRS[rel]; a, b = next((a, b) for s, r, a, b in SEED_BLOCKS if s == s_ and r == r_); assert min(seeds) >= a and max(seeds) <= b, f"{rel} has seeds outside its declared block"
        rows.append(dict(dir=rel, files=len(files), seeds=f"{min(seeds)}-{max(seeds)}", n_seeds=len(seeds), splits=",".join(sorted(str(x) for x in splits if x)), budgets=",".join(str(int(x)) for x in sorted(b for b in budgets if isinstance(b, (int, float)) and b == b)),
                         n_learners=len({x for x in learners if x}), n_selectors=len({x for x in selectors if x}), declared_block=block))
    inv = pd.DataFrame(rows); inv.to_csv(L.TABLES / "inventory.csv", index=False); blocks.to_csv(L.TABLES / "seed_blocks.csv", index=False)
    L.write(L.TABLES / "inventory.md", L.to_md(inv, "{}")); L.write(L.TABLES / "seed_blocks.md", L.to_md(blocks, "{}")); print(len(inv), "directories;", len(blocks), "blocks; no overlaps; confirmation directories inside their blocks")


if __name__ == "__main__":
    main()
